def clean_data(data, remove_empty_strings=True, remove_special_characters=True):
    """
    Clean the input data by removing empty strings and special characters.

    Args:
        data (list or str): The data to be cleaned.
        remove_empty_strings (bool): Whether to remove empty strings from the data.
        remove_special_characters (bool): Whether to remove special characters from the data.

    Returns:
        list or str: The cleaned data.
    """
    if isinstance(data, str):
        if remove_special_characters:
            data = re.sub(r'[^a-zA-Z0-9\s]', '', data)
        if remove_empty_strings:
            data = data.strip()
        return data
    elif isinstance(data, list):
        cleaned_data = []
        for item in data:
            if remove_empty_strings and isinstance(item, str) and item.strip() == '':
                continue
            cleaned_item = item
            if remove_special_characters and isinstance(item, str):
                cleaned_item = re.sub(r'[^a-zA-Z0-9\s]', '', item)
            cleaned_data.append(cleaned_item)
        return cleaned_data
    else:
        raise TypeError("Unsupported data type for cleaning")

def transform_data(data, transformation_rules):
    """
    Transform the input data according to the given rules.

    Args:
        data (list or str): The data to be transformed.
        transformation_rules (dict): A dictionary of transformation rules.

    Returns:
        list or str: The transformed data.
    """
    if isinstance(data, str):
        for rule in transformation_rules:
            data = rule(data)
        return data
    elif isinstance(data, list):
        transformed_data = []
        for item in data:
            transformed_item = item
            for rule in transformation_rules:
                transformed_item = rule(transformed_item)
            transformed_data.append(transformed_item)
        return transformed_data
    else:
        raise TypeError("Unsupported data type for transformation")

