import git
import os
import json
import subprocess

class DataVersioningSystem:
    def __init__(self, repo_path):
        self.repo_path = repo_path
        self.repo = git.Repo(repo_path)
        self.git = self.repo.git

    def create_new_branch(self, branch_name):
        self.git.checkout('main')
        self.git.branch(branch_name)
        self.git.checkout(branch_name)

    def commit_changes(self, message):
        self.git.add('.')
        self.git.commit('-m', message)

    def push_to_remote(self, branch_name):
        self.git.push('origin', branch_name)

    def merge_branches(self, source_branch, target_branch):
        self.git.checkout(target_branch)
        self.git.merge(source_branch)

    def pull_changes(self, branch_name):
        self.git.checkout(branch_name)
        self.git.pull('origin', branch_name)

    def list_branches(self):
        branches = self.git.branch('--list')
        return branches.split('\n')

    def create_new_dataset(self, dataset_name):
        dataset_path = os.path.join(self.repo_path, dataset_name)
        os.makedirs(dataset_path, exist_ok=True)
        return dataset_path

    def save_dataset(self, dataset_path, file_name, data):
        file_path = os.path.join(dataset_path, file_name)
        with open(file_path, 'w') as f:
            json.dump(data, f)

    def load_dataset(self, dataset_path, file_name):
        file_path = os.path.join(dataset_path, file_name)
        with open(file_path, 'r') as f:
            data = json.load(f)
        return data

    def run_script(self, script_path):
        subprocess.run(['python', script_path])

    def get_commit_history(self):
        history = self.git.log('--pretty=format:%H %ad %an %s', '--date=iso')
        return history.split('\n')

    def get_file_history(self, file_path):
        history = self.git.log('--pretty=format:%H %ad %an %s', '--date=iso', '--', file_path)
        return history.split('\n')

    def get_branch_history(self, branch_name):
        history = self.git.log('--pretty=format:%H %ad %an %s', '--date=iso', branch_name)
        return history.split('\n')

    def get_file_diff(self, file_path):
        diff = self.git.diff('--', file_path)
        return diff

    def get_branch_diff(self, branch_name):
        diff = self.git.diff('main', branch_name)
        return diff

