class FunctionDocumenter(MethodDocumenter):
    def get_doc(self):
        doc = super().get_doc()
        if not doc:
            return ''
        return prepare_docstring(doc, self.obj, self.options)

class ClassDocumenter(Documenter):
    def get_doc(self):
        doc = super().get_doc()
        if not doc:
            return ''
        return prepare_docstring(doc, self.obj, self.options)

